@page "/dashboard"
@rendermode InteractiveServer
@using sv_fcf224136b1b48ab8e44a3a5f4fcaec8.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IAsyncDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Site: @WarehouseState.SelectedWarehouseName</h5>
        <p class="card-text">
            Low-stock alerts:
            <span class="badge @BadgeClass fs-6">@AlertService.LastLowStockCount items</span>
        </p>
        <p class="text-muted small mb-0">
            Polling every 10 seconds. Last check: @_lastCheckTime?.ToString("HH:mm:ss")
        </p>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private DateTime? _lastCheckTime;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    private string BadgeClass => AlertService.LastLowStockCount switch
    {
        > 10 => "bg-danger",
        > 5 => "bg-warning text-dark",
        > 0 => "bg-info",
        _ => "bg-secondary"
    };

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(async () =>
        {
            // Warehouse changed — immediately re-poll for the new site
            await PollAsync();
            StateHasChanged();
        });
        WarehouseState.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await PollAsync();
            StateHasChanged();
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await PollAsync();
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task PollAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.SelectedWarehouseId);
        _lastCheckTime = DateTime.Now;
        // This notifies ALL subscribers (sidebar badge, this page, etc.)
        AlertService.UpdateAlertCount(count);
    }

    public async ValueTask DisposeAsync()
    {
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;

        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
        _timer?.Dispose();
    }
}

